mapper.select:
select count(sef.id) as 'classifyNum',
sef.emergency_event_type_name as 'classifyName',
sef.emergency_event_type_code as 'classifyCode'
from safety_emergency_file sef
left join market_config mc on mc.market_tenant = sef.market_tenant

    mc.status = true

        and sef.market_tenant = #{query.marketTenant}


        and sef.create_time >= #{query.period.begin} and sef.create_time < #{query.period.end}


GROUP BY sef.emergency_event_type_code order by classifyNum desc;

select
sef.*
from
safety_emergency_file sef
left join market_config mc on mc.market_tenant = sef.market_tenant
where mc.status = true

    and sef.level_code = #{query.levelCode}


    and sef.expiration_status = #{query.status}


    and sef.create_time >= #{query.period.begin} and sef.create_time < #{query.period.end}


    and sef.market_tenant = #{query.marketTenant}


    and sef.emergency_event_type_code = #{query.classifyCode}


    and sef.name like concat('%',#{query.keyword},'%');

select count(sef.id) as total_num from safety_emergency_file sef left join market_config mc on mc.market_tenant = sef.market_tenant where mc.status = true
and sef.create_time >= #{query.period.begin} and sef.create_time < #{query.period.end}
and sef.market_tenant = #{query.marketTenant}

select count(sef.id) as total_num from safety_emergency_file sef left join market_config mc on mc.market_tenant = sef.market_tenant where mc.status = true
and sef.market_tenant in
#{marketTenantId}
and sef.create_time >= #{query.createdPeriod.begin} and sef.create_time < #{query.createdPeriod.end}
